WITH RECURSIVE serie(n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM serie WHERE n < 5
)
SELECT n FROM serie;

WITH RECURSIVE dias(dia) AS (
    SELECT '2026-09-01'
    UNION ALL
    SELECT date(dia, '+1 day') FROM dias WHERE dia < '2026-09-30'
)
SELECT COUNT(*) AS dias, MIN(dia) AS desde, MAX(dia) AS hasta FROM dias;

WITH RECURSIVE meses(mes) AS (
    SELECT '2025-11'
    UNION ALL
    SELECT strftime('%Y-%m', mes || '-01', '+1 month') FROM meses WHERE mes < '2026-09'
)
SELECT mes FROM meses;

